
const WORDS=[{"id": 0, "w": "节食", "p": "jiéshí", "t": "动词", "m": "ăn kiêng", "coll": "节食经历、过度节食", "s": "她在日记中记录了自己过去节食的经历。"}, {"id": 1, "w": "报道", "p": "bàodào", "t": "名词／动词", "m": "bài báo; đưa tin", "coll": "新闻报道、报道比赛", "s": "这篇新闻报道介绍了比赛的基本情况。"}, {"id": 2, "w": "营养", "p": "yíngyǎng", "t": "名词", "m": "chất dinh dưỡng", "coll": "营养知识、营养成分", "s": "老师请同学们查找有关食物营养的资料。"}, {"id": 3, "w": "摄入", "p": "shèrù", "t": "动词", "m": "hấp thu", "coll": "摄入食物、摄入量", "s": "这张表记录了参与者每天摄入食物的情况。"}, {"id": 4, "w": "模式", "p": "móshì", "t": "名词", "m": "kiểu, mô hình", "coll": "学习模式、工作模式", "s": "学校正在尝试一种新的教学模式。"}, {"id": 5, "w": "波动", "p": "bōdòng", "t": "动词", "m": "dao động, nhấp nhô", "coll": "价格波动、情绪波动", "s": "最近，这种商品的价格波动比较大。"}, {"id": 6, "w": "总共", "p": "zǒnggòng", "t": "副词", "m": "cả thảy, tất cả", "coll": "总共十人、总共花费", "s": "这次活动总共有三十位同学参加。"}, {"id": 7, "w": "参与", "p": "cānyù", "t": "动词", "m": "tham dự, tham gia", "coll": "参与讨论、参与活动", "s": "她积极参与班级的各项活动。"}, {"id": 8, "w": "人员", "p": "rényuán", "t": "名词", "m": "nhân viên", "coll": "工作人员、相关人员", "s": "工作人员正在向大家介绍活动安排。"}, {"id": 9, "w": "相对", "p": "xiāngduì", "t": "形容词", "m": "tương đối", "coll": "相对稳定、相对简单", "s": "和上一题相比，这道题相对简单一些。"}, {"id": 10, "w": "类型", "p": "lèixíng", "t": "名词", "m": "loại", "coll": "不同类型、活动类型", "s": "这个网站提供了不同类型的学习资料。"}, {"id": 11, "w": "称", "p": "chēng", "t": "动词", "m": "cân", "coll": "称重量、称一称", "s": "寄包裹之前，她先称了一下包裹的重量。"}, {"id": 12, "w": "可靠", "p": "kěkào", "t": "形容词", "m": "đáng tin cậy", "coll": "可靠的消息、可靠的方法", "s": "写文章时，我们应该使用可靠的资料。"}, {"id": 13, "w": "纳入", "p": "nàrù", "t": "动词", "m": "đưa vào", "coll": "纳入计划、纳入考虑范围", "s": "这个建议已经被纳入下一步的工作计划。"}, {"id": 14, "w": "分析", "p": "fēnxī", "t": "动词", "m": "phân tích", "coll": "分析问题、分析数据", "s": "大家认真分析了调查的结果，并提出了建议。"}, {"id": 15, "w": "志愿者", "p": "zhìyuànzhě", "t": "名词", "m": "người tình nguyện", "coll": "一名志愿者、志愿者活动", "s": "那位志愿者正在帮助客人找到会议室。"}, {"id": 16, "w": "跟踪", "p": "gēnzōng", "t": "动词", "m": "theo dõi, theo sát", "coll": "跟踪进度、跟踪调查", "s": "项目负责人每周都会跟踪工作的进度。"}, {"id": 17, "w": "成果", "p": "chéngguǒ", "t": "名词", "m": "thành quả, kết quả", "coll": "研究成果、取得成果", "s": "经过几个月的努力，这个小组取得了不错的成果。"}, {"id": 18, "w": "清晰", "p": "qīngxī", "t": "形容词", "m": "rõ ràng, rõ rệt", "coll": "画面清晰、表达清晰", "s": "这张照片的画面很清晰，每个人的表情都看得见。"}, {"id": 19, "w": "即", "p": "jí", "t": "动词／副词", "m": "nghĩa là; ngay", "coll": "即现在、即是", "s": "这份报告分为三个部分，即背景、方法和结果。"}, {"id": 20, "w": "升", "p": "shēng", "t": "动词", "m": "lên cao", "coll": "升高、温度上升", "s": "雨停后，河里的水位又升高了一些。"}, {"id": 21, "w": "达到", "p": "dádào", "t": "动词", "m": "đạt đến", "coll": "达到目标、达到要求", "s": "只要坚持练习，你就有机会达到自己的目标。"}, {"id": 22, "w": "意外", "p": "yìwài", "t": "形容词／名词", "m": "bất ngờ; điều bất trắc", "coll": "感到意外、意外的结果", "s": "听到这个结果，大家都感到有些意外。"}, {"id": 23, "w": "存在", "p": "cúnzài", "t": "动词", "m": "tồn tại", "coll": "存在问题、客观存在", "s": "讨论以后，大家发现这个方案还存在一些问题。"}, {"id": 24, "w": "明显", "p": "míngxiǎn", "t": "形容词", "m": "rõ ràng, nổi bật", "coll": "明显变化、效果明显", "s": "经过一段时间的练习，他的口语有了明显的进步。"}, {"id": 25, "w": "补偿", "p": "bǔcháng", "t": "动词", "m": "đền bù, bổ khuyết", "coll": "补偿损失、给予补偿", "s": "商店向顾客道歉，并对造成的损失进行了补偿。"}, {"id": 26, "w": "立即", "p": "lìjí", "t": "副词", "m": "lập tức, ngay", "coll": "立即出发、立即回答", "s": "接到通知后，大家立即前往集合地点。"}, {"id": 27, "w": "趋势", "p": "qūshì", "t": "名词", "m": "xu hướng, chiều hướng", "coll": "发展趋势、变化趋势", "s": "这份报告分析了近几年市场的变化趋势。"}, {"id": 28, "w": "差异", "p": "chāyì", "t": "名词", "m": "sự khác biệt", "coll": "存在差异、个体差异", "s": "不同地区的人们在饮食习惯上可能存在一些差异。"}, {"id": 29, "w": "联合", "p": "liánhé", "t": "动词／形容词", "m": "kết hợp, hợp nhất; chung", "coll": "联合举办、联合行动", "s": "两所学校将联合举办一场文化交流活动。"}, {"id": 30, "w": "个别", "p": "gèbié", "t": "形容词", "m": "riêng lẻ, cá biệt", "coll": "个别学生、个别情况", "s": "大部分同学已经交了作业，只有个别同学还没交。"}, {"id": 31, "w": "表明", "p": "biǎomíng", "t": "动词", "m": "thể hiện, chứng tỏ", "coll": "结果表明、调查表明", "s": "调查结果表明，大多数同学喜欢小组讨论。"}, {"id": 32, "w": "临时", "p": "línshí", "t": "副词／形容词", "m": "đến lúc; tạm thời", "coll": "临时决定、临时通知", "s": "因为天气变化，他们临时决定改天再出发。"}, {"id": 33, "w": "现象", "p": "xiànxiàng", "t": "名词", "m": "hiện tượng", "coll": "常见现象、观察现象", "s": "老师请同学们仔细观察这个现象。"}, {"id": 34, "w": "非", "p": "fēi", "t": "动词", "m": "không phải, không", "coll": "并非如此、是非", "s": "这件事并非像你想的那么简单。"}, {"id": 35, "w": "就餐", "p": "jiùcān", "t": "动词", "m": "đi ăn", "coll": "在餐厅就餐、错峰就餐", "s": "会议结束后，大家一起到附近的餐厅就餐。"}, {"id": 36, "w": "放纵", "p": "fàngzòng", "t": "动词", "m": "buông thả, không kiểm soát", "coll": "放纵自己、不能放纵", "s": "遇到困难时，他没有放纵自己，而是继续努力。"}, {"id": 37, "w": "苗条", "p": "miáotiáo", "t": "形容词", "m": "thon thả, mảnh khảnh", "coll": "身材苗条、苗条的身影", "s": "照片里有一个穿着长裙的苗条身影。"}, {"id": 38, "w": "借口", "p": "jièkǒu", "t": "名词／动词", "m": "cớ; lấy cớ", "coll": "寻找借口、当作借口", "s": "他不应该把准备不足当作借口。"}, {"id": 39, "w": "采取", "p": "cǎiqǔ", "t": "动词", "m": "áp dụng, dùng", "coll": "采取措施、采取方法", "s": "发现问题后，负责人立即采取了措施。"}, {"id": 40, "w": "措施", "p": "cuòshī", "t": "名词", "m": "biện pháp", "coll": "有效措施、安全措施", "s": "为了保证活动顺利进行，大家制定了详细的安全措施。"}];
